script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'isListView',
		value: false
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api}) {
	return api.state.isListView ? 'secondary' :'primary' ;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'isListView',
		value: true
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api}) {
	return api.state.isListView ? 'primary' : 'secondary';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var categories = api.context.props.categories;
    var label = api.context.props.categories[0].label;
    if (api.context.props.categoryViewport) {
        var category = categories.find(o => o.id === api.context.props.categoryViewport);
        label = category.label;
    }

    return helpers.translateSync('No data collected for the KPIs in {0} category.', label);
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: "Benchmark kpi detail views",
        value: {
            "tabName": api.context.props.tabLabel,
            "kpiName": event.context.item.value.name
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: "Benchmark kpi detail views",
        value: {
            "tabName": api.context.props.tabLabel,
            "kpiName": event.payload.cell.label
        }
    };
}
